"""Apply or reverse the numbered migrations in migrations/.

python migrate.py up <db> applies every pending migration; python migrate.py
down <db> reverses the newest applied one.
"""
import sqlite3
import sys
from pathlib import Path

FOLDER = Path(__file__).resolve().parent / "migrations"


def migrations():
    for up_file in sorted(FOLDER.glob("*.up.sql")):
        yield up_file.name.split("_", 1)[0], up_file, up_file.with_name(
            up_file.name.replace(".up.sql", ".down.sql"))


def applied(conn):
    conn.execute("CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY)")
    return {row[0] for row in conn.execute("SELECT version FROM schema_migrations")}


def up(path):
    conn = sqlite3.connect(path)
    done = applied(conn)
    for version, up_file, _ in migrations():
        if version not in done:
            conn.executescript("BEGIN;\n%s\nINSERT INTO schema_migrations VALUES ('%s');\nCOMMIT;"
                               % (up_file.read_text(encoding="utf-8"), version))
    conn.close()


def down(path):
    conn = sqlite3.connect(path)
    done = applied(conn)
    for version, _, down_file in reversed(list(migrations())):
        if version in done:
            conn.executescript("BEGIN;\n%s\nDELETE FROM schema_migrations WHERE version = '%s';\nCOMMIT;"
                               % (down_file.read_text(encoding="utf-8"), version))
            break
    conn.close()


if __name__ == "__main__":
    {"up": up, "down": down}[sys.argv[1]](sys.argv[2])

