"""Payment provider client. charge() is a network call to the provider."""
import threading
import time


class Declined(Exception):
    pass


class FakeProvider:
    """Records calls; charges once per idempotency key, like the provider."""

    def __init__(self, delay=0.0, decline=False):
        self.delay, self.decline = delay, decline
        self.calls, self.charged = [], {}
        self._lock = threading.Lock()

    def charge(self, key, amount_cents):
        with self._lock:
            self.calls.append((key, amount_cents))
        time.sleep(self.delay)
        if self.decline:
            raise Declined(key)
        with self._lock:
            return self.charged.setdefault(key, "ch_%s" % key)
